INSERT INTO "WarnNotice" (id,state,employer,"normalizedEmployer",source,"noticeDate","effectiveDate",employees,"layoffType",county,industry,"sourceUrl")
SELECT 'kybf_'||md5(v."normalizedEmployer"||'|'||v."noticeDate"||'|'||coalesce(v.employees::text,'')||'|'||coalesce(v.county,'')),
       'KY', v.employer, v."normalizedEmployer", 'WARN_FILING', v."noticeDate"::timestamp, v."effectiveDate"::timestamp, v.employees, v."layoffType", v.county, v.industry,
       CASE v."sourceUrl" WHEN 'C' THEN 'https://kyworks.ky.gov/Services/Documents/Website-WARN%20Notice%20Report%2011042026.xlsx' ELSE 'https://kyworks.ky.gov/Services/Documents/Prior%20Year%20Warn%20Notices.xlsx' END
FROM v
WHERE NOT EXISTS (
  SELECT 1 FROM "WarnNotice" w
  WHERE w.state='KY' AND w."normalizedEmployer"=v."normalizedEmployer" AND w."noticeDate"=v."noticeDate"::timestamp
    AND w.employees IS NOT DISTINCT FROM v.employees
)
ON CONFLICT (id) DO NOTHING;

UPDATE "WarnNotice" SET county='Jefferson' WHERE state='KY' AND source='WARN_FILING' AND county ~* '^Jefferson( county)?( - .*)?$' AND county <> 'Jefferson';
